'use strict';
const D=window.ATLAS_DATA,$=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const read=(k,f)=>{try{return JSON.parse(localStorage.getItem(k))??f}catch{return f}};
let drafts=read('bee_posts',[]);const selected=[D.nodes[0],D.nodes.find(n=>/格林/.test(n.title)),D.nodes.find(n=>/投影/.test(n.title))].filter(Boolean);
const seeds=selected.map((n,i)=>({id:'note-'+n.id,title:n.title,category:'数学札记',date:'2026-11-07',summary:['从积分微元出发，辨清对象，再选择计算路径。','闭合曲线、正向与区域内的光滑性，缺一不可。','先消元得到投影关系，再检查空间交线是否存在。'][i],html:n.html,node:n.id,seed:true}));
let published=[];const posts=()=>[...drafts,...published,...seeds];
function toast(s){$('#notice').textContent=s;$('#notice').style.display='block';setTimeout(()=>$('#notice').style.display='none',2600)}
function save(){try{localStorage.setItem('bee_posts',JSON.stringify(drafts));return true}catch{toast('保存失败，请导出备份并检查浏览器空间');return false}}
const row=p=>`<a class="journal-row" href="#/post/${encodeURIComponent(p.id)}"><span class="meta">${esc(p.category)}<br>${esc(p.date)}${p.seed?'<br>整理稿':p.published?'':'<br>本地草稿'}</span><div><h3>${esc(p.title)}</h3><p>${esc(p.summary||'打开阅读')}</p></div><span>↗</span></a>`;
function home(){return `<div class="wrap"><section class="hero"><div><h1>雪落纸上，<br>思考有声。</h1><p>这里是 Bee 的个人书房。<br>收藏数学的秩序，也为日常留一页空白。</p><a class="primary" href="study.html#/home">走进数学书房 ↗</a></div><figure class="art-stage" data-art="monet"><div class="art-window"><button class="art-enlarge" aria-label="放大欣赏当前画作"><img class="art-image" src="assets/monet-snow.jpg" alt="莫奈《阳光下的雪中麦垛》，1891年"></button></div><figcaption><span class="art-credit">莫奈 · 阳光下的雪中麦垛，1891</span><div class="art-switch"><button data-paint="monet" aria-pressed="true">莫奈</button><button data-paint="vangogh" aria-pressed="false">梵高</button></div></figcaption></figure></section><section class="section"><div class="section-head"><h2>书房札记</h2><a href="#/journal">全部文章 ↗</a></div>${posts().slice(0,3).map(row).join('')}</section></div><section class="study-band"><div><h2>沿着一条曲线，<br>走进数学。</h2><p>从一道题出发，找到方法之间的联系。<br>知识、练习与理解，在这里慢慢连成一张图。</p><div class="stats"><span><strong>${D.modules.length}</strong>章节</span><span><strong>${D.nodes.length}</strong>方法</span><span><strong>${D.exercises.length}</strong>题目</span></div></div><ul><li><a href="study.html#/atlas">展开知识图谱 <span>↗</span></a></li><li><a href="study.html#/problems">题目与完整解析 <span>↗</span></a></li><li><a href="study.html#/practice">练习方法判断 <span>↗</span></a></li><li><a href="study.html#/review">回看学习记录 <span>↗</span></a></li></ul></section><div class="wrap"><section class="quiet-gallery"><img src="assets/vangogh-orchard.webp" alt="盛开的果园" loading="lazy"><img src="assets/vangogh-roses.jpg" alt="玫瑰" loading="lazy"><img src="assets/monet-river.jpg" alt="河岸" loading="lazy"></section><div class="art-teaser"><a href="atelier.html#art">走进画与声收藏馆 · 38 幅绘画与 9 套长篇纯音乐 ↗</a></div><section class="about-strip"><h2>关于这间书房</h2><div><p>留一点安静给阅读，<br>留一点耐心给尚未理解的问题。</p><a href="#/about">认识 Bee ↗</a></div></section></div>`}
function library(){return `<div class="wrap"><div class="page-title"><h1>数学书房</h1><p>曲线与曲面积分，按章节展开。每个方法连接原题、解析与训练。</p><div class="actions"><a class="primary" href="study.html#/atlas">打开完整图谱 ↗</a><a class="primary" href="study.html#/practice">开始训练 ↗</a></div></div><div class="chapter">${D.modules.map(m=>`<a href="study.html#/atlas?module=${encodeURIComponent(m.id)}"><h3>${esc(m.title)}</h3><p>${esc(m.subtitle)}</p><span class="meta">${D.nodes.filter(n=>n.module===m.id).length} 个方法 · ${D.exercises.filter(e=>e.module===m.id).length} 道题 ↗</span></a>`).join('')}</div><section class="section"><h2>带着问题读札记</h2>${seeds.map(row).join('')}</section></div>`}
function article(id){let p=posts().find(p=>p.id===id);if(!p)return '<div class="wrap page-title"><h1>这页暂不存在</h1><a href="#/journal">返回随笔</a></div>';return `<article class="reading"><a href="#/journal">← 随笔</a><h1 style="margin-top:30px">${esc(p.title)}</h1><p class="meta">${esc(p.category)} · ${esc(p.date)} · ${p.seed?'根据原积分图谱整理':p.published?'Bee':'本地草稿，仅当前浏览器可见'}</p>${p.seed?p.html:p.body.split(/\n\s*\n/).map(t=>'<p>'+esc(t).replaceAll('\n','<br>')+'</p>').join('')}${p.published?'':p.node?`<div class="related"><h3>把理解带回题目</h3><p>在原专题里查看相关题目与详细方法。</p><a href="study.html#/method/${p.node}">打开对应知识点 →</a></div>`:`<div class="actions"><a href="#/editor/${p.id}">继续编辑</a><button id="delete-post">删除草稿</button></div>`}</article>`}
function editor(id){let p=drafts.find(p=>p.id===id)||{};return `<div class="editor"><h1>写一页</h1><p class="meta">草稿保存在当前浏览器。保存后可在随笔中阅读；导出备份可交给我更新到正式网站。</p><form id="post-form"><label for="post-title">标题</label><input id="post-title" value="${esc(p.title||'')}" required maxlength="100"><label for="post-category">分类</label><select id="post-category">${['日常随笔','数学札记','读书记录','网站手记'].map(c=>`<option ${c===p.category?'selected':''}>${c}</option>`).join('')}</select><label for="post-body">正文</label><textarea id="post-body" required placeholder="在这里记下今天的思考。用空行分段。">${esc(p.body||'')}</textarea><div class="actions"><button type="submit">保存并阅读</button><button type="button" id="export-posts">导出文章备份</button></div></form></div>`}
function settings(){return `<div class="editor"><h1>备份与设置</h1><p>把文章、图谱修改和学习记录一起保存。建议在更换设备或清理浏览器前导出。</p><div class="actions"><button id="backup">导出全部备份</button><button id="restore">导入备份</button><input id="backup-file" type="file" accept="application/json" hidden></div><h2>数据保存在哪里</h2><p>草稿、收藏、学习进度和训练记录保存在当前浏览器中。这里尚未启用账号同步，备份文件可以手动带到另一台设备。</p><h2>如何添加新题</h2><p>将题目图片、来源与手稿交给我，整理核对后更新到书房。当前网站保留人工审核流程，尚未接入自动识题接口。</p><h2>已有内容</h2><p>${D.exercises.length} 道题目、${D.nodes.length} 个方法、${D.modules.length} 个章节。既有解析原样迁入，本次没有重新逐题校验数学答案。</p></div>`}
function download(obj,name){let u=URL.createObjectURL(new Blob([JSON.stringify(obj,null,2)],{type:'application/json'}));let a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
function route(){let [page='home',id='']=location.hash.replace(/^#\/?/,'').split('/');id=decodeURIComponent(id);let app=$('#main');app.className='reveal';document.querySelectorAll('.bee-site-nav a').forEach(a=>{a.removeAttribute('aria-current');if(a.getAttribute('href')==='#/'+page)a.setAttribute('aria-current','page')});if(page==='home')app.innerHTML=home();else if(page==='library'){location.href='study.html#/home';return}else if(page==='journal'){app.innerHTML=`<div class="wrap"><div class="page-title"><h1>随笔与札记</h1><p>记录理解的过程，也收藏日常的片刻。数学札记来自原积分图谱，个人随笔等待你写下。</p><a href="#/editor">写一页 ↗</a></div><div class="filters"><button class="active" data-filter="全部">全部</button><button data-filter="数学札记">数学札记</button><button data-filter="日常随笔">日常随笔</button><button data-filter="读书记录">读书记录</button><button data-filter="网站手记">网站手记</button></div><div id="post-list">${posts().map(row).join('')}</div></div>`;document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-filter]').forEach(x=>x.classList.toggle('active',x===b));let list=posts().filter(p=>b.dataset.filter==='全部'||p.category===b.dataset.filter);$('#post-list').innerHTML=list.length?list.map(row).join(''):'<p class="empty">这一页还留着空白。<a href="#/editor">写下第一篇 →</a></p>'})}else if(page==='post')app.innerHTML=article(id);else if(page==='editor')app.innerHTML=editor(id);else if(page==='settings')app.innerHTML=settings();else if(page==='about')app.innerHTML=`<article class="reading"><h1>你好，我是 Bee。</h1><p>这是一间关于数学、阅读与日常的个人书房。</p><p>数学书房收录曲线与曲面积分的知识图谱、题目解析和方法训练。希望每一道题都能连接到一种可以理解、可以再次使用的方法。</p><h2>雪霁之后</h2><p>纸页、油画、宋体字与安静的留白，是这间书房的底色。给漫长的推导一个清晰的版面，也给零散的思考一个可以回来的地方。</p><h2>联系 Bee</h2><p><a href="mailto:nothingjudgeus@gmail.com">nothingjudgeus@gmail.com</a></p><h2>书房的约定</h2><p>题目保留来源，推导尽量完整。文章里的理解可以持续修订，学习记录可以导出保存。</p><a href="study.html#/home">去数学书房 →</a></article>`;else{location.hash='#/home';return}window.scrollTo(0,0);
if($('#post-form'))$('#post-form').onsubmit=e=>{e.preventDefault();let p={id:id||'draft-'+Date.now(),title:$('#post-title').value.trim(),category:$('#post-category').value,date:new Date().toLocaleDateString('sv-SE'),body:$('#post-body').value,summary:$('#post-body').value.slice(0,75)};if(!p.title||!p.body.trim())return;let old=drafts;drafts=[p,...drafts.filter(x=>x.id!==p.id)];if(save()){location.hash='#/post/'+p.id;toast('草稿已保存')}else drafts=old};
if($('#delete-post'))$('#delete-post').onclick=()=>{if(confirm('删除这篇本地草稿？')){drafts=drafts.filter(x=>x.id!==id);save();location.hash='#/journal'}};
if($('#export-posts'))$('#export-posts').onclick=()=>download({format:'bee-posts-v1',posts:drafts},'bee-articles.json');
if($('#backup'))$('#backup').onclick=()=>{let data={};for(let i=0;i<localStorage.length;i++){let k=localStorage.key(i);if(k.startsWith('snow_atlas_')||['bee_posts','bee_sound','bee_motion','bee_volume','bee_art_choice','bee_music_choice','bee_music_loop'].includes(k))data[k]=localStorage.getItem(k)}download({format:'bee-library-v1',date:new Date().toISOString(),data},'bee-library-backup.json')};
if($('#restore')){$('#restore').onclick=()=>$('#backup-file').click();$('#backup-file').onchange=async e=>{try{let b=JSON.parse(await e.target.files[0].text());if(b.format!=='bee-library-v1'||!b.data||typeof b.data!=='object')throw Error();let entries=Object.entries(b.data);for(let [k,v]of entries){if(!(['bee_posts','bee_sound','bee_motion','bee_volume','bee_art_choice','bee_music_choice','bee_music_loop'].includes(k)||k.startsWith('snow_atlas_'))||typeof v!=='string')throw Error();if(k==='bee_posts'||k.startsWith('snow_atlas_'))JSON.parse(v)}if(!confirm('导入会覆盖备份中对应的本地记录。继续？'))return;for(let [k,v]of entries)localStorage.setItem(k,v);drafts=read('bee_posts',[]);toast('备份已恢复')}catch{toast('导入失败：请使用有效的书房备份文件')}}}}
$('#search-open').onclick=()=>{$('#search-dialog').showModal();$('#search-input').focus()};$('#search-close').onclick=()=>$('#search-dialog').close();$('#search-input').oninput=e=>{let q=e.target.value.trim().toLowerCase();if(!q){$('#search-results').innerHTML='';return}let results=[...posts().map(p=>({title:p.title,sub:p.category,href:'#/post/'+p.id})),...D.exercises.map(x=>({title:x.id+' · '+x.title,sub:x.method,href:'study.html#/problem/'+x.id})),...D.nodes.map(n=>({title:n.title,sub:'知识点',href:'study.html#/method/'+n.id}))].filter(r=>(r.title+' '+r.sub).toLowerCase().includes(q));$('#search-results').innerHTML=results.length?results.slice(0,30).map(r=>`<a href="${r.href}">${esc(r.title)}<small>${esc(r.sub)}</small></a>`).join(''):'<p>没有找到相关内容，换一个关键词试试。</p>';$('#search-results').querySelectorAll('a').forEach(a=>a.onclick=()=>$('#search-dialog').close())};document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key==='k'){e.preventDefault();$('#search-open').click()}});window.addEventListener('hashchange',route);route();

fetch('content/posts.json').then(r=>{if(!r.ok)throw Error('posts');return r.json()}).then(data=>{if(!Array.isArray(data))throw Error('posts');published=data.filter(p=>p&&typeof p.id==='string'&&typeof p.title==='string'&&typeof p.body==='string').map(p=>({...p,published:true}));route()}).catch(()=>{});
